// middleware/auth.global.ts
export default defineNuxtRouteMiddleware((to) => {
  const me = useState('me')
  if (!me.value && to.path !== '/login') {
    return navigateTo('/login')
  }
})

export default defineNuxtRouteMiddleware((to, from) => {
  if (to.params.id === 'banned') {
    return abortNavigation('このページは閲覧できません')
  }
  if (to.path === '/old') {
    return navigateTo('/new', { redirectCode: 301 })
  }
})

export default defineNuxtRouteMiddleware((to) => {
  // ✅ Cookie ベース → サーバ/クライアント両対応
  const token = useCookie('token').value
  if (!token && to.path !== '/login') return navigateTo('/login')

  // ❌ サーバで ReferenceError: localStorage is not defined
  // const t = localStorage.getItem('token')
})

export default defineNuxtRouteMiddleware(async (to) => {
  const me = useState('me', () => null)
  if (!me.value) {
    me.value = await $fetch('/api/me').catch(() => null)
  }
  if (!me.value && to.meta.requiresAuth) {
    return navigateTo('/login')
  }
})

// middleware/auth.global.ts
export default defineNuxtRouteMiddleware((to) => {
  const token = localStorage.getItem('token')
  if (!token) navigateTo('/login')
})

export default defineNuxtRouteMiddleware(async () => {
  const me = useState('me', () => null)
  if (!me.value) {
    me.value = await $fetch('/api/me')
  }
})
